// Neither number is specified by the brief - both are named placeholders standing in for a real
// decision, same pattern as every other undecided-but-not-blocking value in this repo. Set real
// values here (or via env vars) once the actual thresholds are decided; nothing else about this
// workflow needs to change.
const MIN_TENURE_DAYS = Number($env.PLACEHOLDER_REFERRAL_TENURE_DAYS || 90);
const MIN_ENGAGEMENT_SCORE = Number($env.PLACEHOLDER_REFERRAL_ENGAGEMENT_THRESHOLD || 70);

const results = [];
for (const item of $input.all()) {
  const company = item.json;
  const tenureDays = company.liveClientSince
    ? Math.floor((Date.now() - new Date(company.liveClientSince).getTime()) / 86400000)
    : 0;
  const eligible = tenureDays >= MIN_TENURE_DAYS && (company.engagementScore ?? 0) >= MIN_ENGAGEMENT_SCORE;
  if (eligible) {
    results.push({ json: { companyId: company.id, companyName: company.name, tenureDays, engagementScore: company.engagementScore } });
  }
}
return results;
